mapper.select:
 WHERE b.tenant_id=#{tenantId} AND b.store_id=#{storeId}
GROUP BY b.cost_dimension_key,b.warehouse_id,b.sku_id,b.last_cost_ledger_sequence,b.record_version,b.updated_at
HAVING b.last_cost_ledger_sequence<>COALESCE(MAX(l.cost_ledger_sequence),0)
ORDER BY b.updated_at,b.cost_dimension_key LIMIT #{limit}
